import numpy as np
def fragments(A,c):
    M=A==c; H,W=M.shape
    seen=np.zeros_like(M,bool); out=[]
    for i in range(H):
        for j in range(W):
            if M[i,j] and not seen[i,j]:
                st=[(i,j)]; cells=[]; seen[i,j]=True
                while st:
                    r,c2=st.pop()
                    cells.append((r,c2))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=r+dr,c2+dc
                        if 0<=rr<H and 0<=cc<W and M[rr,cc] and not seen[rr,cc]:
                            seen[rr,cc]=True; st.append((rr,cc))
                out.append(cells)
    return out
